    Definition hda (L : list ent) (t : Z) : Z := match L with [] => t | b :: _ => addr b end.
    Fixpoint lnk (M : mem) (Ls : list ent) (t : Z) : Prop :=
      match Ls with
      | [] => True
      | a :: Ls' => cell8 SEGS M (addr a) (hda Ls' t) /\ lnk M Ls' t
      end.

